// MEDIUM for the flow, LOW for the interpolation math.
bIsFirstTube = false;
if (!SkyTubeGate())                                    // 0x1426f5f90 gate, plus global _DAT_1478df42c != 0
{
    return;
}
if (CurrentSkyTube == SkyTube)                          // +0x7A8, no change
{
    return;
}
bIsFirstTube = (CurrentSkyTube == nullptr && SkyTube != nullptr);
CurrentSkyTube = SkyTube;
if (SkyTube != nullptr && (ProjectileFlags & 1))        // +0x6F4 bit 0
{
    OnEnteredSkyTubeWhileSimulating(true);            // 0x143f84060(this, 1)
}
ForceNetUpdate();                                       // vslot 0x5E8 -> 0x143f72550 (AActor::ForceNetUpdate)
if (SkyTubeCounter != -1)                               // byte +0x635, saturating increment
{
    SkyTubeCounter = SkyTubeCounter + 1;
}
if (bIsFirstTube && CurrentSkyTube != nullptr && Role == ROLE_Authority)   // Role byte +0xF0 == 3
{
    float Factor = GetTubeScalar(SkyTube + 0x478, 0) * ProjectileSpeedScalar;   // 0x14070fdf0 * float at +0x7A4
    if (Factor != 0.0f)
    {
        // target vector: from this[0x26] (+0x130) via 0x1440e9d30 when present, else the fixed default vector
        FVector Target = (TubeTargetComponent != nullptr) ? GetTubeVector(TubeTargetComponent) : DefaultTubeVector;
        InterpolateTubeLocation(SkyTube, Target, Factor);     // 0x1426f9da0; writes the location pair at ProjectileMovementComponent (this[0x640]) +0xC4 and +0xCC, factor clamped to 1.0
    }
}
